<?php
require_once __DIR__.'/../../config/db.php';
require_once __DIR__.'/../../middleware/role.php';
require_once __DIR__.'/../employee/model.php';
require_once __DIR__.'/../employee/payroll.php';
require_once __DIR__.'/attendance.php';
function tfQ($sql,$params=[]){global $conn;$s=$conn->prepare($sql);if($params)$s->bind_param(str_repeat('s',count($params)),...$params);$s->execute();return $s;}
function tfRows($sql,$params=[]){return tfQ($sql,$params)->get_result()->fetch_all(MYSQLI_ASSOC);}
function tfOne($sql,$params=[]){return tfQ($sql,$params)->get_result()->fetch_assoc();}
function tfConfig($section){$map=[
 'candidates'=>['table'=>'teamflow_candidates','resource'=>'teamflow_candidates','owner'=>'user_id','date'=>'created_at'],
 'projects'=>['table'=>'teamflow_projects','resource'=>'teamflow_projects','owner'=>'created_by','date'=>'created_at'],
 'issues'=>['table'=>'teamflow_issues','resource'=>'teamflow_issues','owner'=>'assignee_user_id','date'=>'created_at'],
 'timesheets'=>['table'=>'teamflow_weekly_timesheets','resource'=>'teamflow_timesheets','owner'=>'user_id','date'=>'created_at'],
 'reports'=>['table'=>'teamflow_reports','resource'=>'teamflow_reports','owner'=>'userId','date'=>'createdAt'],
 'attendance'=>['table'=>'teamflow_employee_work_status','resource'=>'teamflow_attendance','owner'=>'user_id','date'=>'login_time']];if(!isset($map[$section]))throw new InvalidArgumentException('Unknown TeamFlow resource.');return $map[$section];}
function tfAllScope($permission){return ($permission['data_scope']??'OWN')==='ALL';}
function tfName(){return "COALESCE(NULLIF(TRIM(CONCAT_WS(' ',c.firstname,c.lastname)),''),u.nick_name,u.email)";}
function tfProjectsFor($userId){$ids=[];foreach(tfRows('SELECT id FROM teamflow_projects WHERE lead_user_id=? OR created_by=?',[$userId,$userId]) as $r)$ids[]=(int)$r['id'];foreach([['teamflow_issues','project','assignee_user_id'],['teamflow_weekly_timesheets','project_id','user_id'],['teamflow_employee_work_status','project_id','user_id'],['teamflow_user_project_assignments','project_id','user_id']] as [$table,$project,$owner])foreach(tfRows("SELECT DISTINCT `$project` project_id FROM `$table` WHERE `$owner`=?",[$userId]) as $r)if(ctype_digit((string)$r['project_id']))$ids[]=(int)$r['project_id'];foreach(tfRows('SELECT project_id,team_members FROM teamflow_teams') as $r){$members=json_decode($r['team_members'],true)?:[];if(in_array((string)$userId,array_map('strval',$members),true))$ids[]=(int)$r['project_id'];}foreach(tfRows('SELECT t.project_id FROM teamflow_project_team_members m JOIN teamflow_teams t ON t.id=m.team_id WHERE m.user_id=?',[$userId]) as $r)$ids[]=(int)$r['project_id'];return array_values(array_unique(array_filter($ids)));}
function tfWhere($section,$user,$permission,$alias='a'){$cfg=tfConfig($section);if(tfAllScope($permission))return ['1=1',[]];if($section==='projects'){$ids=tfProjectsFor((int)$user['id']);return $ids?[$alias.'.id IN('.implode(',',array_fill(0,count($ids),'?')).')',$ids]:['1=0',[]];}if($section==='issues')return ["($alias.assignee_user_id=? OR $alias.created_by=?)",[$user['id'],$user['id']]];return [$alias.'.`'.$cfg['owner'].'`=?',[$user['id']]];}
function tfFind($section,$id,$user,$permission){$cfg=tfConfig($section);[$where,$params]=tfWhere($section,$user,$permission);$deleted=$section!=='candidates'?' AND a.deleted_at IS NULL':'';return tfOne('SELECT a.* FROM `'.$cfg['table'].'` a WHERE a.id=? AND '.$where.$deleted,array_merge([$id],$params));}
function tfAttachFiles($section,$row){$type=['projects'=>'projects','issues'=>'issues','reports'=>'reports','attendance'=>'employee_work_status'][$section]??null;$row['files']=$type?tfRows('SELECT id,original_name,mime_type,file_size,missing,entity_type FROM teamflow_files WHERE entity_type=? AND entity_id=?',[$type,$row['id']]):[];if($section==='projects'){$docs=tfRows('SELECT f.id,f.original_name,f.mime_type,f.file_size,f.missing,f.entity_type FROM teamflow_files f JOIN teamflow_project_documents d ON d.id=f.entity_id WHERE f.entity_type=\'project_documents\' AND d.project_id=?',[$row['id']]);$row['files']=array_merge($row['files'],$docs);}if($section==='attendance'){$docs=tfRows('SELECT f.id,f.original_name,f.mime_type,f.file_size,f.missing,f.entity_type FROM teamflow_files f JOIN teamflow_employee_status_documents d ON d.id=f.entity_id WHERE f.entity_type=\'employee_status_documents\' AND d.work_status_id=?',[$row['id']]);$row['files']=array_merge($row['files'],$docs);}return $row;}
function tfList($section,$query,$user,$permission,$export=false){$cfg=tfConfig($section);[$where,$params]=tfWhere($section,$user,$permission);if($section!=='candidates')$where.=' AND a.deleted_at IS NULL';$search=trim((string)($query['search']??''));$owner=$cfg['owner'];$join=' LEFT JOIN users u ON u.id=a.`'.$owner.'` LEFT JOIN teamflow_candidates c ON c.user_id=u.id';$name=tfName();$extra=",$name user_name,u.email username";
 if($section==='projects'){$join=' LEFT JOIN users u ON u.id=a.lead_user_id LEFT JOIN teamflow_candidates c ON c.user_id=u.id';$extra=",$name lead_name,u.email username";$searchCols=['a.name','a.projectKey','a.description'];}
 elseif($section==='candidates'){$join=' JOIN users u ON u.id=a.user_id';$extra=",COALESCE(NULLIF(TRIM(CONCAT_WS(' ',a.firstname,a.lastname)),''),u.nick_name,u.email) legal_name,u.email username,u.status account_status";$searchCols=['a.firstname','a.lastname','u.email'];}
 else{$searchCols=[$name,'u.email'];$fields=['issues'=>['summary','description','status'],'timesheets'=>['task_name','worked_on','status'],'reports'=>['reportText'],'attendance'=>['module_name','working_on','worked_on','status']];foreach($fields[$section] as $f)$searchCols[]='a.`'.$f.'`';$projectColumn=$section==='issues'?'a.project':'a.project_id';if(in_array($section,['issues','timesheets','attendance'],true)){$join.=' LEFT JOIN teamflow_projects p ON p.id='.$projectColumn;$extra.=',p.name project_name';}}
 if(!empty($query['candidate_id'])&&in_array($section,['timesheets','reports','attendance','candidates'],true)){$candidate=tfAttendanceTarget($query,$user,$permission);$where.=' AND a.`'.$cfg['owner'].'`=?';$params[]=$candidate['user_id'];}
 if($search!==''){$where.=' AND ('.implode(' OR ',array_map(fn($f)=>$f.' LIKE ?',$searchCols)).')';foreach($searchCols as $_)$params[]='%'.$search.'%';}
 foreach(['from'=>'>=','to'=>'<='] as $key=>$operator)if(!empty($query[$key])){$date=employeeCollectionDate($query[$key],'Filter date',true);$where.=' AND DATE(a.`'.$cfg['date'].'`)'.$operator.'?';$params[]=$date;}
 if(!empty($query['project_id'])&&in_array($section,['issues','timesheets','attendance'],true)){$where.=' AND a.`'.($section==='issues'?'project':'project_id').'`=?';$params[]=(int)$query['project_id'];}
 if(!empty($query['status'])&&in_array($section,['issues','timesheets','attendance'],true)){$where.=' AND a.status=?';$params[]=$query['status'];}
 $count=(int)tfOne('SELECT COUNT(*) total FROM `'.$cfg['table'].'` a'.$join.' WHERE '.$where,$params)['total'];$limit=$export?10000:max(5,min(100,(int)($query['limit']??10)));$page=max(1,(int)($query['page']??1));$totalPages=max(1,(int)ceil($count/$limit));$page=min($page,$totalPages);
 $rows=tfRows('SELECT a.*'.$extra.' FROM `'.$cfg['table'].'` a'.$join.' WHERE '.$where.' ORDER BY a.`'.$cfg['date'].'` DESC,a.id DESC LIMIT ? OFFSET ?',array_merge($params,[$limit,($page-1)*$limit]));
 foreach($rows as &$row){if($section==='candidates'){unset($row['profile_json'],$row['collection_json'],$row['photo_json']);$row['candidate_code']='TF-C-'.str_pad((string)$row['id'],4,'0',STR_PAD_LEFT);}else $row=tfAttachFiles($section,$row);}unset($row);return ['data'=>$rows,'total'=>$count,'page'=>$page,'total_pages'=>$totalPages,'limit'=>$limit];}
function tfOptions($user,$permission){$name=tfName();$candidates=tfRows("SELECT c.id,c.user_id,$name name,u.email username,u.status FROM teamflow_candidates c JOIN users u ON u.id=c.user_id".(tfAllScope($permission)?'':' WHERE c.user_id=?').' ORDER BY name',tfAllScope($permission)?[]:[$user['id']]);$projectPermission=$permission;$projects=tfList('projects',['limit'=>100],$user,$projectPermission,true)['data'];$projects=array_map(fn($p)=>['id'=>$p['id'],'name'=>$p['name'],'projectKey'=>$p['projectKey']],$projects);if(tfAllScope($permission)){$candidates=tfRows("SELECT u.id user_id,c.id,COALESCE(NULLIF(TRIM(CONCAT_WS(' ',c.firstname,c.lastname)),''),u.nick_name,u.email) name,u.email username,u.status FROM users u JOIN positions p ON p.id=u.position_id LEFT JOIN teamflow_candidates c ON c.user_id=u.id WHERE LOWER(p.position_name)='candidate' ORDER BY name");}return ['users'=>$candidates,'projects'=>$projects];}
function tfCheckProject($id,$user,$permission){if(!$id)return;if(!tfFind('projects',(int)$id,$user,$permission))throw new DomainException('The project is not assigned to this account.');}
function tfText($input,$field,$max=500,$required=false){$value=employeeCollectionText($input[$field]??'',$field,$max);if($required&&$value==='')throw new InvalidArgumentException($field.' is required.');return $value;}
function tfTarget($input,$user,$permission,$existing=null){$target=$existing?(int)($existing['user_id']??$existing['userId']??$user['id']):(int)($input['user_id']??$user['id']);if(!tfAllScope($permission))$target=(int)$user['id'];if(!tfOne('SELECT id FROM teamflow_candidates WHERE user_id=?',[$target]))throw new InvalidArgumentException('Select a TeamFlow candidate.');return $target;}
function tfWriteRow($table,$data,$id=null){global $conn;if($id){$pairs=array_map(fn($key)=>'`'.$key.'`=?',array_keys($data));tfQ('UPDATE `'.$table.'` SET '.implode(',',$pairs).' WHERE id=?',array_merge(array_values($data),[$id]));return $id;}tfQ('INSERT INTO `'.$table.'` (`'.implode('`,`',array_keys($data)).'`) VALUES('.implode(',',array_fill(0,count($data),'?')).')',array_values($data));return (int)$conn->insert_id;}
function tfSave($section,$input,$user,$permission,$existing=null){$cfg=tfConfig($section);$id=$existing['id']??null;$data=[];
 if($section==='projects'){$data=['name'=>tfText($input,'name',255,true),'projectKey'=>tfText($input,'projectKey',100,true),'type'=>tfText($input,'type',100),'description'=>tfText($input,'description',20000),'projectURL'=>tfText($input,'projectURL',500)];if($data['projectURL']!==''&&!preg_match('#^https?://#i',$data['projectURL']))throw new InvalidArgumentException('Project URL must begin with https:// or http://.');$lead=(int)($input['lead_user_id']??0);if($lead&&!tfOne('SELECT id FROM teamflow_candidates WHERE user_id=?',[$lead]))throw new InvalidArgumentException('Select a TeamFlow project lead.');$data['lead_user_id']=$lead?:null;$data['lead']=$lead?(string)$lead:null;if(!$id)$data['created_by']=$user['id'];}
 elseif($section==='issues'){$project=(int)($input['project']??0);tfCheckProject($project,$user,$permission);if(!$project)throw new InvalidArgumentException('Project is required.');$assignee=tfAllScope($permission)?(int)($input['assignee_user_id']??$user['id']):(int)$user['id'];if(!tfOne('SELECT id FROM teamflow_candidates WHERE user_id=?',[$assignee]))throw new InvalidArgumentException('Select a TeamFlow assignee.');$data=['project'=>(string)$project,'assignee_user_id'=>$assignee,'assignee'=>(string)$assignee,'summary'=>tfText($input,'summary',1000,true)];foreach(['description','issue_type','status','priority','team','labels','sprint','linked_issue_type','linked_issue'] as $field)$data[$field]=tfText($input,$field,$field==='description'?30000:255);if(!$id)$data['created_by']=$user['id'];}
 elseif($section==='timesheets'){if($existing&&($existing['source_type']??'')==='attendance')return tfSubmitAutomaticSheet($input,$existing);$target=tfTarget($input,$user,$permission,$existing);if($existing&&!tfAllScope($permission)&&!in_array($existing['status'],['Draft','Rejected'],true))throw new DomainException('Only draft or rejected timesheets can be edited.');$year=filter_var($input['year']??null,FILTER_VALIDATE_INT);$week=filter_var($input['week_no']??null,FILTER_VALIDATE_INT);if(!$year||$year<2000||$year>2100||!$week||$week<1||$week>53)throw new InvalidArgumentException('Provide a valid ISO week and year.');$type=$input['entry_type']??'project';if(!in_array($type,['project','leave','training'],true))throw new InvalidArgumentException('Invalid entry type.');$project=(int)($input['project_id']??0);if($type==='project'&&!$project)throw new InvalidArgumentException('Choose a project.');tfCheckProject($project,$user,$permission);$data=['user_id'=>$target,'year'=>$year,'week_no'=>$week,'entry_type'=>$type,'project_id'=>$project?:null,'task_name'=>tfText($input,'task_name',255,true),'worked_on'=>tfText($input,'worked_on',20000)];$total=0;foreach(['mon','tue','wed','thu','fri','sat','sun'] as $day){$hours=$input[$day.'_hours']??0;if(!is_numeric($hours)||(float)$hours<0||(float)$hours>24)throw new InvalidArgumentException('Daily hours must be between 0 and 24.');$data[$day.'_hours']=round((float)$hours,2);$total+=$data[$day.'_hours'];}$data['total_hours']=round($total,2);$status=$input['status']??'Draft';if(!in_array($status,['Draft','Pending'],true))$status=$existing['status']??'Draft';$data['status']=$status;}
 elseif($section==='reports'){$data=['userId'=>tfTarget($input,$user,$permission,$existing),'reportText'=>tfText($input,'reportText',50000,true)];if(!$id)$data['reportImage']='';}
 elseif($section==='attendance'){if($existing&&tfOne('SELECT id FROM teamflow_timesheet_worklogs WHERE session_id=? LIMIT 1',[$existing['id']]))throw new DomainException('This completed session is linked to a timesheet. Its recorded clock times are locked.');if(!tfAllScope($permission))throw new DomainException('Use Clock In / Clock Out to record your attendance.');$project=(int)($input['project_id']??0);tfCheckProject($project,$user,$permission);$target=tfTarget($input,$user,$permission,$existing);$candidate=tfOne('SELECT id FROM teamflow_candidates WHERE user_id=?',[$target]);$data=['user_id'=>$target,'candidate_id'=>$candidate['id'],'project_id'=>$project,'module_name'=>tfText($input,'module_name',100),'working_on'=>tfText($input,'working_on',20000),'worked_on'=>tfText($input,'worked_on',20000),'status'=>tfText($input,'status',50)];foreach(['login_time','logout_time'] as $field){$value=str_replace('T',' ',trim($input[$field]??''));if(strlen($value)===16)$value.=':00';if($value!==''&&!DateTimeImmutable::createFromFormat('!Y-m-d H:i:s',$value))throw new InvalidArgumentException('Invalid attendance date/time.');$data[$field]=$value?:null;}if(!$data['login_time'])throw new InvalidArgumentException('Login time is required.');if($data['logout_time']&&$data['logout_time']<$data['login_time'])throw new InvalidArgumentException('Logout cannot precede login.');$data['login_status']=$data['logout_time']?0:1;}
 else throw new InvalidArgumentException('Unsupported update.');
 return tfWriteRow($cfg['table'],$data,$id);}
function tfStorage(){ $root=getenv('TEAMFLOW_FILE_DIR')?:dirname(__DIR__,4).'/e2e_teamflow_files';if(!is_dir($root)&&!mkdir($root,0700,true))throw new RuntimeException('TeamFlow storage is unavailable.');$real=realpath($root);$web=realpath($_SERVER['DOCUMENT_ROOT']??dirname(__DIR__,2));if($web&&str_starts_with(strtolower($real),strtolower($web).DIRECTORY_SEPARATOR))throw new RuntimeException('TeamFlow storage must be outside the public web root.');return $real;}
function tfReceiveFile($file,$type,$entity,$user,$replace=null){if(!$file||($file['error']??UPLOAD_ERR_NO_FILE)===UPLOAD_ERR_NO_FILE)return null;if(($file['error']??1)!==UPLOAD_ERR_OK||!is_uploaded_file($file['tmp_name'])||$file['size']>15*1024*1024||$file['size']<1)throw new InvalidArgumentException('Upload a file up to 15 MB.');$mime=(new finfo(FILEINFO_MIME_TYPE))->file($file['tmp_name']);$allowed=['image/jpeg','image/png','image/webp','application/pdf','application/msword','application/vnd.openxmlformats-officedocument.wordprocessingml.document','application/zip','text/plain','text/csv','text/x-sql','application/sql','video/mp4','application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'];if(!in_array($mime,$allowed,true))throw new InvalidArgumentException('Unsupported document type.');if($type==='candidate_photo'&&(!in_array($mime,['image/jpeg','image/png','image/webp'],true)||$file['size']>5*1024*1024||!getimagesize($file['tmp_name'])))throw new InvalidArgumentException('Use a JPG, PNG or WebP photo up to 5 MB.');$dimensions=$type==='candidate_photo'?getimagesize($file['tmp_name']):null;if($dimensions&&($dimensions[0]>8000||$dimensions[1]>8000||$dimensions[0]*$dimensions[1]>24000000))throw new InvalidArgumentException('Photo dimensions are too large. Use an image under 24 megapixels.');$stored=bin2hex(random_bytes(24)).'.bin';$path=tfStorage().DIRECTORY_SEPARATOR.$stored;if(!move_uploaded_file($file['tmp_name'],$path))throw new RuntimeException('Upload storage is unavailable.');chmod($path,0600);try{$name=basename(str_replace('\\','/',(string)$file['name']));if(strlen($name)>240)throw new InvalidArgumentException('Filename is too long.');$data=['entity_type'=>$type,'entity_id'=>$entity,'storage_name'=>$stored,'original_name'=>$name,'original_path'=>$replace['original_path']??$name,'mime_type'=>$mime,'file_size'=>$file['size'],'missing'=>0,'uploaded_by'=>$user['id']];if(!$replace)$data['created_at']=date('Y-m-d H:i:s');$id=tfWriteRow('teamflow_files',$data,$replace['id']??null);return $id;}catch(Throwable $e){unlink($path);throw $e;}}
function tfFileOwner($file){$type=$file['entity_type'];$id=$file['entity_id'];if(in_array($type,['projects','issues','reports'],true))return [$type,(int)$id];if($type==='employee_work_status')return ['attendance',(int)$id];if($type==='project_documents'){$row=tfOne('SELECT project_id FROM teamflow_project_documents WHERE id=?',[$id]);return ['projects',(int)($row['project_id']??0)];}if($type==='employee_status_documents'){$row=tfOne('SELECT work_status_id FROM teamflow_employee_status_documents WHERE id=?',[$id]);return ['attendance',(int)($row['work_status_id']??0)];}if($type==='candidate_photo')return ['candidates',(int)$id];throw new DomainException('File access denied.');}
function tfProfile($userId){$row=tfOne('SELECT c.*,u.email username,u.status account_status FROM teamflow_candidates c JOIN users u ON u.id=c.user_id WHERE c.user_id=?',[$userId]);if(!$row)return null;$row['profile']=json_decode($row['profile_json']?:'{}',true)?:[];$row['collection']=employeePublicCollection(employeeDecodeCollection($row['collection_json']));$row['candidate_code']='TF-C-'.str_pad((string)$row['id'],4,'0',STR_PAD_LEFT);$row['photo']=tfOne("SELECT id,original_name FROM teamflow_files WHERE entity_type='candidate_photo' AND entity_id=? AND missing=0 ORDER BY id DESC LIMIT 1",[$row['id']]);unset($row['profile_json'],$row['collection_json'],$row['photo_json']);return $row;}
function tfSaveProfile($candidate,$input,$user,$admin){global $conn;$paths=[];$existing=employeeDecodeCollection($candidate['collection_json']);$profile=json_decode($candidate['profile_json']?:'{}',true)?:[];$data=[];foreach(['firstname','lastname','contact_info','current_address','permanent_address'] as $field)$data[$field]=tfText($input,$field,str_contains($field,'address')?5000:($field==='contact_info'?80:100));$data['birthdate']=employeeCollectionDate($input['birthdate']??'','Birth date')?:null;foreach(['gender','personal_email','linkedin_profile','professional_title','skills','about'] as $key)$profile[$key]=tfText($input['profile']??[],$key,$key==='about'?5000:500);if($profile['personal_email']!==''&&!filter_var($profile['personal_email'],FILTER_VALIDATE_EMAIL))throw new InvalidArgumentException('Enter a valid personal email.');if($admin)$profile['wfh_allowed']=!empty($input['profile']['wfh_allowed']);$collection=employeeNormalizeCollection($input['collection']??$existing,$existing,false);if(!$admin)$collection['review']=$existing['review']??['reviewed_by'=>'','date'=>''];if(isset($input['collection']['declaration']['accepted']))$collection['declaration']=['accepted'=>$input['collection']['declaration']['accepted']===true,'date'=>date('Y-m-d')];
 $photoPath=null;$conn->begin_transaction();try{if(!empty($input['remove_photo']))tfQ("UPDATE teamflow_files SET missing=1 WHERE entity_type='candidate_photo' AND entity_id=?",[$candidate['id']]);employeeReceiveDocuments($collection,$paths);if(isset($_FILES['photo'])){$photoId=tfReceiveFile($_FILES['photo'],'candidate_photo',$candidate['id'],$user);if($photoId){$photoRow=tfOne('SELECT storage_name FROM teamflow_files WHERE id=?',[$photoId]);$photoPath=tfStorage().DIRECTORY_SEPARATOR.$photoRow['storage_name'];}}$data['profile_json']=json_encode($profile);$data['collection_json']=payrollEncryptValue(json_encode($collection,JSON_UNESCAPED_UNICODE));$data['updated_at']=date('Y-m-d H:i:s');tfWriteRow('teamflow_candidates',$data,$candidate['id']);$conn->commit();}catch(Throwable $e){$conn->rollback();employeeCleanupDocuments($paths);if($photoPath&&is_file($photoPath))unlink($photoPath);throw $e;}}
function tfClock($input,$user,$permission){
 global $conn;$target=(int)$user['id'];$candidate=tfOne('SELECT * FROM teamflow_candidates WHERE user_id=?',[$target]);if(!$candidate)throw new DomainException('This account is not linked to a TeamFlow candidate.');
 $instant=new DateTimeImmutable('now',new DateTimeZone('UTC'));$now=$instant->setTimezone(new DateTimeZone('America/New_York'))->format('Y-m-d H:i:s');$utc=$instant->format('Y-m-d H:i:s');$conn->begin_transaction();
 try{tfQ('SELECT id FROM teamflow_candidates WHERE user_id=? FOR UPDATE',[$target]);$open=tfOne("SELECT * FROM teamflow_employee_work_status WHERE user_id=? AND clock_source='profile' AND deleted_at IS NULL AND login_status=1 AND logout_time IS NULL ORDER BY id DESC LIMIT 1",[$target]);
  if(($input['action']??'')==='in'){if($open)throw new DomainException('You are already clocked in.');$project=(int)($input['project_id']??0);if(!$project)throw new InvalidArgumentException('Choose your assigned project.');tfCheckProject($project,$user,$permission);
   $id=tfWriteRow('teamflow_employee_work_status',['user_id'=>$target,'candidate_id'=>$candidate['id'],'project_id'=>$project,'login_time'=>$now,'created_at'=>$now,'login_status'=>1,'clock_source'=>'profile','login_utc'=>$utc,'module_name'=>tfText($input,'module_name',100,true),'working_on'=>tfText($input,'working_on',20000,true),'progress_percent'=>0,'status'=>'Working']);
  }elseif(($input['action']??'')==='out'){if(!$open)throw new DomainException('No open work session was found.');$id=$open['id'];$update=['logout_time'=>$now,'logout_utc'=>$utc,'worked_on'=>tfText($input,'worked_on',20000,true),'progress_percent'=>tfWorkProgress($input),'blockers'=>tfText($input,'blockers',5000),'status'=>'Completed','login_status'=>0];tfWriteRow('teamflow_employee_work_status',$update,$id);tfAutomaticTimesheets(array_merge($open,$update));
  }else throw new InvalidArgumentException('Choose Clock In or Clock Out.');$conn->commit();return $id;
 }catch(Throwable $e){$conn->rollback();throw $e;}
}

function tfSaveWithAttachment($section,$input,$user,$permission,$row){
 global $conn;$filePath=null;$type=['projects'=>'projects','issues'=>'issues','reports'=>'reports','attendance'=>'employee_work_status'][$section]??null;
 $conn->begin_transaction();
 try{$id=tfSave($section,$input,$user,$permission,$row);
  if($type&&isset($_FILES['attachment'])){$fileId=tfReceiveFile($_FILES['attachment'],$type,$id,$user);if($fileId){$file=tfOne('SELECT storage_name FROM teamflow_files WHERE id=?',[$fileId]);$filePath=tfStorage().DIRECTORY_SEPARATOR.$file['storage_name'];}}
  $conn->commit();return $id;
 }catch(Throwable $error){$conn->rollback();if($filePath&&is_file($filePath))unlink($filePath);throw $error;}
}
